["jacket_desc"] = "UYRUĞU: AMERİKALI$NL;YAŞI: BİLİNMİYOR$NL;$NL;SÖYLENTİYE GÖRE BİR ZAMANLAR MİAMİ’DEKİ RUS MAFYASININ TAMAMINI TEK BAŞINA YOK ETMİŞ. ASKERÎ GEÇMİŞİ VE AŞIRI ŞİDDET KARŞISINDA GÖZÜNÜ BİLE KIRPMAMASI, ONU MÜKEMMEL BİR KİRALIK KATİL; BAZILARININ DEYİMİYLE BİR \"HABERCİ\" YAPIYOR. BİLİNMEYEN BİR NEDENLE HİÇ KONUŞMUYOR VE YALNIZCA BİR TEYP YARDIMIYLA İLETİŞİM KURUYOR. KONUŞMAK YERİNE DİL ÖĞRENME KASETLERİNDEN, ANONSLARDAN VE BELGESEL ANLATIMLARINDAN PARÇALAR ÇALIYOR.",
["jfe_chas_intro_01_01"] = "TAMAM, ŞEF, ANLAT BAKALIM.",
["jfe_chas_intro_01_02"] = "NE APTAL AMA. BU MANDARİN... VE BİLMEK İSTEMEZSİN.",
["jfe_chas_intro_02_01"] = "SON ZAMANLARDA SAN FRANCISCO'DA ÇETE ÇATIŞMALARI ARTTI... SFPD DE GERGİN. ÇOK SES ÇIKARIRSANIZ... KENDİNİZİ ÇATIŞMANIN İÇİNDE BULURSUNUZ.",
["jfe_chas_intro_02_02"] = "HA, DOĞRU. BİR ŞEY DAHA. AÇIK ARTIRMAYI YÖNETEN YAŞLI BİR ADAM VAR. EĞER... ÖLÜRSE... ARKASINDAN AĞLAYAN OLMAZ.",
["jfe_chas_intro_03_01"] = "EVET, JOY'LA... EPEY MACERA YAŞADIK... LOS ANGELES'TA.",
["jfe_chas_intro_03_02"] = "BECERİSİNİ... VE DEĞERİNİ KANITLADI. KARŞILIK VERMENİN DOĞRU OLACAĞINI DÜŞÜNDÜM. BANA YARDIM ETTİKTEN SONRA ONU O... GÖTLERİN ELİNE... BIRAKMAK YAKIŞIK ALMAZDI, DEĞİL Mİ?",
["jfe_sand_01_01"] = "YOLDAYIM. YANGINI GÖRÜYORUM. BİRAZ DAYANIN, TAMAM MI?",
["jfe_sand_01_02"] = "AZ KALDI. DİKKATLİ OLMALIYIM, YOKSA KIYAMETİ KOPARIRLAR.",
["jfe_sand_01_03"] = "ŞU AN RIHTIMLARDA BİR SÜRÜ ADAMLARI VAR. YAVAŞ İLERLEMEK GEREK. BİR DAKİKA VERİN, TAMAM MI?",
["jfe_sand_02_01"] = "HADİ, SENİ BURADAN ÇIKARALIM. HÂLÂ NASIL HAYATTA BU ADAM?",
["jfe_sand_03_01"] = "HADİ, SENİ BURADAN ÇIKARALIM. HÂLÂ NASIL HAYATTA BU ADAM?",
["jfe_sand_04_01"] = "BURADAYIM MİLLET, KIÇINIZI TEKNEYE ATIN DA GİDELİM.",
["jfe_sand_04_02"] = "SİZ HAZIR OLUNCA BEN DE HAZIRIM MİLLET. MİAMİ VİCE USULÜ KAÇALIM BURADAN.",
["jfe_sand_04_03"] = "TAMAM ŞEFLER, ADAMINIZI BURADAN ÇIKARALIM. BİNİN!",
["jfe_sand_05_01"] = "SİKTİR, BENİ NİŞANA ALDILAR GALİBA. ACELE EDİN!",
["jfe_sand_05_02"] = "NEYİ BEKLİYORSUNUZ APTALLAR?",
["jfe_sand_05_03"] = "YAKINDA BENZİNİM BİTECEK...",
["jfe_sand_intro1a_01"] = "BUNA GERÇEKTEN VAKTİMİZ VAR MI?",
["jfe_sand_intro1a_02"] = "TAMAM, SÖYLE BAKALIM ŞEF. HEY, DİKKAT ET!!",
["jfe_sand_intro1a_03"] = "HÂLÂ MANDARİN, ŞEF. BİR ÖNCEKİNDEN DE ANLAMSIZDI, DEĞİL Mİ?",
["jfe_sand_intro1a_04"] = "EVET. BUNLARI SANA HANGİ SALAK ÖĞRETTİ?",
["jfe_sand_intro1b_01"] = "BİLDİĞİNİ SANDIĞIN LAFLARDAN BİRİNİ DAHA SÖYLE BAKALIM.",
["jfe_sand_intro1b_02"] = "BU MİNİBÜSÜ DAHA DA YAVAŞLATACAK DEĞİL YA! ODAKLANMAMA YARDIM EDİYOR, DEĞİL Mİ?",
["jfe_sand_intro1b_03"] = "HÂLÂ MANDARİN ŞEF. BİR ÖNCEKİNDEN BİLE ANLAMSIZDI.",
["jfe_sand_intro1b_04"] = "EVET. EE... BUNLARI SANA HANGİ SALAK ÖĞRETTİ?",
["jfe_sand_intro2a_01"] = "TABİİ ŞEF, GÖRDÜĞÜMDEN ÖTEYE ARABA SÜRMEM ZATEN, DEĞİL Mİ?",
["jfe_sand_intro2a_02"] = "ESKİ ÇİN ATASÖZÜ.",
["jfe_sand_intro2a_03"] = "HAYIR APTAL.",
["jfe_sand_intro2a_04"] = "BOŞ VER ŞEF.",
["jfe_sand_intro3a_01"] = "YUFU WANG'I GERÇEKTEN KIZDIRMIŞSINIZ. SİZİN VLAD, BUZLUKTA NE TUTTUĞUNUZU BİLMİYORDUR UMARIM, HA?",
["jfe_sand_intro3a_02"] = "NE KADAR BELALI?",
["jfe_sand_intro4a_01"] = "GOLDEN DAGGER'DAKİ BAĞLANTILARIMDAN SÖYLENTİLER DUYUYORUM.",
["jfe_sand_intro4a_02"] = "ONLARA VURMANIZ, LİDERLİĞE DUYULAN GÜVENİ SARSIYOR. EJDERHAYI TAM TUVALETTEYKEN FENA KIZDIRDINIZ DOĞRUSU.",
["jfe_sand_intro4a_03"] = "HEM DE OLDUKÇA CİDDİYE ALIYOR, DEĞİL Mİ?",
["jimmy_desc"] = "UYRUĞU: BİLİNMİYOR$NL;YAŞI: BİLİNMİYOR$NL;$NL;BAŞTA ŞÜPHELERİM VARDI, KABUL EDİYORUM. AMA JIMMY, CRIME.NET DÜZEYİNDE BİR SOYGUNCU OLARAK SİVRİLMEK İÇİN GEREKEN BÜTÜN BECERİLERE SAHİP OLDUĞUNU GÖSTERDİ. SINIR TANIMIYOR, HİÇBİR SÖZLEŞMEYİ GERİ ÇEVİRMİYOR VE HER GÜNÜNÜ SON GÜNÜYMÜŞ GİBİ YAŞIYOR. SADIK BİRİ VE İHTİYACIMIZ OLDUĞUNU HİÇ DÜŞÜNMEDİĞİM KADAR İYİ BİR TAKVİYE OLDUĞUNU KANITLADI.",
["jowi_desc"] = "UYRUĞU: AMERİKALI$NL;YAŞI: 40’LI YAŞLARINDA$NL;$NL;JOHN WICK SESSİZ VE SAKİN BİR ESKİ KİRALIK KATİLDİR. MUHTEMELEN BOKS GEÇMİŞİ SAYESİNDE, YILLARIN ETKİLEMEDİĞİ BİR FİZİĞE SAHİPTİR. JOHN VE CHAINS ESKİDEN ORDUDA BİRLİKTE GÖREV YAPTIKLARI İÇİN BİRBİRLERİNİ TANIRLAR.$NL;$NL;BİR SÜRE ORTADAN KAYBOLAN JOHN, YAKIN ZAMANDA YENİDEN ORTAYA ÇIKTI VE CHAINS’İ HASSAS BİR DURUMDAN KURTARDI. KARŞILIĞINDA CHAINS’E BİR EKİBE İHTİYACI OLDUĞUNU SÖYLEDİ. CHAINS ESKİ BİR DOSTA NASIL HAYIR DİYEBİLİRDİ?",
["jowi_desc_codex"] = "JOHN, EN BÜYÜK SUÇ ÖRGÜTLERİNDEN BAZILARININ TANIDIĞI, KORKULAN BİR TETİKÇİYDİ. UZUN SÜRE ORTADAN KAYBOLDUKTAN SONRA YAKIN ZAMANDA YENİDEN ORTAYA ÇIKTI VE CHAINS'İ HASSAS BİR DURUMDAN KURTARDI. KARŞILIĞINDA JOHN, CHAINS'E BİR EKİBE İHTİYACI OLDUĞUNU SÖYLEDİ. CHAINS NASIL HAYIR DİYEBİLİRDİ? ESKİ DOSTUNA YARDIM ETMEK İÇİN ONU PAYDAY GANG'E DAVET ETTİ. ",
["joy_desc"] = "UYRUĞU: JAPON-AMERİKALI$NL;YAŞI: 22$NL;$NL;JOY, ERGENLİĞİNİN İLK YILLARINDAN BERİ SİBER SUÇLU. TEKNOLOJİ VE BİLGİSAYAR SÖZ KONUSU OLDUĞUNDA PAHA BİÇİLEMEZ, YETENEKLİ BİR BİLGİSAYAR KORSANI. AMA SİLAH KULLANMAYI DA BİLİR; GENÇ YAŞINA RAĞMEN SON DERECE DAYANIKLIDIR.",
["legal_text"] = "PAYDAY 2 © 2019 STARBREEZE AB. TÜM HAKLARI SAKLIDIR. PAYDAY 2, PAYDAY, STARBREEZE, STARBREEZE STUDİOS VE STARBREEZE LOGOSU, STARBREEZE AB’NİN İSVEÇ VE/VEYA DİĞER ÜLKELERDEKİ TİCARİ MARKALARI YA DA TESCİLLİ TİCARİ MARKALARIDIR. 505 GAMES TARAFINDAN YAYINLANMIŞTIR. 505 GAMES VE 505 GAMES LOGOSU, 505 GAMES S.R.L.’NİN TESCİLLİ TİCARİ MARKALARIDIR. DİĞER TÜM TİCARİ MARKALAR İLGİLİ SAHİPLERİNE AİTTİR.",
["loading_gameplay_1"] = "SÖZLEŞME ARACISINI DİNLE; SIRADA NE YAPMAN GEREKTİĞİNİ SANA SÖYLER.",
["loading_gameplay_10"] = "BAŞARI EKRANINDA, HAYATTA KALAN HER EKİP ÜYESİ İÇİN BONUS KAZANIRSIN.",
["loading_gameplay_100"] = "YAYDAN ATTIĞIN HER OKUN HASARI, ATIŞI NE KADAR UZUN SÜRE HAZIRLADIĞINA BAĞLI OLARAK ARTAR.",
["loading_gameplay_101"] = "ŞOK BOMBALARI YERE DÜŞTÜKTEN SONRA ATEŞ EDİLEREK, HATTA YAKIN DÖVÜŞ SİLAHIYLA VURULARAK YOK EDİLEBİLİR.",
["loading_gameplay_102"] = "BAZI KAPILARI KİLİTLERİNE ATEŞ EDEREK AÇABİLİRSİN.",
["loading_gameplay_103"] = "KEŞİF MODUNDA DA, ÖZELLİKLE MUHAFIZLARA ÇARPARSAN TESPİT EDİLEBİLİRSİN. ANCAK MUHAFIZLARIN SENİ FARK ETMEYE BAŞLADIĞI MESAFE ÇOK DAHA KISADIR.",
["loading_gameplay_104"] = "SİVİLLER KIRIK KAMERALARI VEYA GANİMET ÇANTALARINI FARK ETMEZ. ANCAK CESET TORBALARINI FARK EDERLER.",
["loading_gameplay_105"] = "CESET TORBALARINI GÜVENLE SAKLAMAK İÇİN DERİN SUYA VEYA ÇÖP KONTEYNERLERİNE ATABİLİRSİN.",
["loading_gameplay_106"] = "POLİSLER, HENÜZ ÇANTALANMAMIŞ GANİMETLERİ GERİ ALMAYA ÇALIŞMAZ.",
["loading_gameplay_107"] = "LAZERLER SANA HASAR VERMEZ AMA ALARMI TETİKLER.",
["loading_gameplay_108"] = "ECM KARIŞTIRICILAR MUHAFIZLARIN ALARM VERMESİNİ ÖNLEYEBİLİR. ANCAK ETKİNKEN HARİTADAKİ BAZI HEDEFLERİN TAMAMLANMASINI DA ENGELLEYEBİLİRLER. BU YÜZDEN ONLARI SON ÇARE OLARAK KULLAN.",
["loading_gameplay_109"] = "ECM KARIŞTIRICILAR, SWAT MİNİBÜSÜ TARETLERİNİ GEÇİCİ OLARAK KENDİ TARAFINA GEÇİRİR.",
["loading_gameplay_11"] = "DÜŞÜK TESPİT RİSKİ, HAYALET BECERİ AĞACIYLA ÇATIŞMADA DA İŞE YARAYABİLİR. BİRİNİN ZIRH GİYMEMESİ, ÇATIŞMADA KENDİNİ SAVUNAMAYACAĞI ANLAMINA GELMEZ.",
["loading_gameplay_110"] = "ECM KARIŞTIRICILARIN GERİ BESLEME İŞLEVİ HER 4 DAKİKADA BİR YENİLENİR.",
["loading_gameplay_111"] = "\"YAKIN DÖVÜŞ\" TUŞUNU BASILI TUTARAK YAKIN DÖVÜŞ SİLAHINI DAHA GÜÇLÜ BİR SALDIRIYA HAZIRLAYABİLİRSİN.",
["loading_gameplay_112"] = "BAZI DÜŞMANLAR VÜCUT ZIRHI KULLANIR. KAFALARINA NİŞAN ALMALISIN.",
["loading_gameplay_113"] = "SWAT MİNİBÜSÜ TARETLERİ, KALKANLARI HER KIRILDIĞINDA BİRER KEZ OLMAK ÜZERE, KENDİLERİNİ İKİ KEZ ONARIR.",
["loading_gameplay_114"] = "SWAT MİNİBÜSÜ TARETİNİN ZAYIF NOKTASI, SİLAHIN ALTINDAKİ YANSITICI KAMERADIR. EN FAZLA HASARI VERMEK İÇİN ORAYA NİŞAN AL.",
["loading_gameplay_115"] = "ÇOĞU PENCERENİN KİLİDİ AÇILABİLİR. CAMI KIRMAK ÇOK GÜRÜLTÜ ÇIKARIR. KIRIK CAM GÖREN SİVİLLER BİLE ŞÜPHELENİR.",
["loading_gameplay_116"] = "BİR PENCEREYİ KIRARSAN, GEÇEN MUHAFIZLARI VE SİVİLLERİ KANDIRMAK İÇİN ONU KAPATACAK TAHTALAR BULMAYA ÇALIŞ.",
["loading_gameplay_117"] = "SUSTURUCULU TESTERELER BİLE BİRAZ SES ÇIKARIR. YAKINDAKİ İNSANLARA DİKKAT ET.",
["loading_gameplay_118"] = "BAĞLANMAMIŞ SİVİLLER GÖZETİMSİZ KALIRSA AYAĞA KALKIP KAÇAR. BUNU ÖNLEMEK İÇİN PLASTİK KELEPÇELERİNİ KULLAN.",
["loading_gameplay_119"] = "ACE OF SPADES FIRLATILABİLİRİ SESSİZDİR. EL BOMBALARI İSE DEĞİLDİR. GİZLİCE İLERLEYECEKSEN HAZIRLIĞINI BUNA GÖRE YAP.",
["loading_gameplay_12"] = "DÜŞMANINI TANI. CLOAKER BİRİMLERİ, YEŞİL PARLAYAN BELİRGİN GECE GÖRÜŞ GÖZLÜKLERİ TAKAR VE ÜZERİNE HÜCUM EDERKEN SES ÇIKARIR. BÖLGEYE GELDİKLERİNDE DE BİR PARAZİT SESİ DUYABİLİRSİN.",
["loading_gameplay_120"] = "ECM KARIŞTIRICILAR KAMERALARI GEÇİCİ OLARAK DEVRE DIŞI BIRAKIR. ZOR DURUMDA KALDIĞINDA KAMERA OPERATÖRÜNÜ KÖR ETMEK İÇİN KULLANMAKTAN ÇEKİNME.",
["loading_gameplay_121"] = "KAMERALAR SES ALGILAYAMAZ; ANCAK ŞÜPHELİ BİR HAREKETİ UZUN SÜRE GÖRÜRLERSE ALARM VERİRLER.",
["loading_gameplay_122"] = "BİR KAMERA ŞÜPHELİ BİR HAREKET GÖRÜRSE ALARMIN ÖNÜNE GEÇEMEZSİN.",
["loading_gameplay_123"] = "YAKIN DÖVÜŞ SİLAHLARI HER ZAMAN SESSİZDİR. SUSTURUCUN YOKSA SESSİZCE DÜŞMAN İNDİRMEK İÇİN EN İYİ DOSTUN ONLARDIR.",
["loading_gameplay_124"] = "MUHAFIZLARA FAZLA YAKLAŞIRSAN ARKALARINDA OLDUĞUNU ANLARLAR. ONLARI TAKİP EDERKEN BİRAZ MESAFE BIRAK.",
["loading_gameplay_125"] = "ÇOĞU SİLAHIN ŞARJÖRÜ, İÇİNDE HÂLÂ MERMİ VARKEN DAHA HIZLI DEĞİŞTİRİLİR.",
["loading_gameplay_126"] = "CAPTAIN WINTERS BÖLGEDE OLDUĞU SÜRECE POLİS SALDIRISI DURMAZ.",
["loading_gameplay_127"] = "SİLAHIN \"TEHDİT\" İSTATİSTİĞİ, ATEŞ ETTİĞİNDE POLİSLERİN ATEŞTEN KAÇINIP SİPER ARAMA İHTİMALİNİ GÖSTERİR. DEĞER YÜKSELDİKÇE SİLAHIN HER ATIŞI DAHA TEHDİTKÂR OLUR",
["loading_gameplay_128"] = "NEREDEYSE TÜM MATKAPLARIN KENDİLİĞİNDEN BOZULMA İHTİMALİ VARDIR. GÖZÜNÜ ÜZERLERİNDEN AYIRMA.",
