["loc_bph_brf_01"] = "TAMAM, BAIN'İN HAPİSHANENİN TAM NERESİNDE TUTULDUĞUNU YA DA NE DURUMDA OLDUĞUNU BİLMİYORUZ. ÜSTELİK HER YERDE MURKY PİSLİKLERİ VAR. BU İŞ ÇOK ÇABUK GÜRÜLTÜYE DÖNECEK, HA? OKYANUSA DÖKÜLEN KANALİZASYON SİSTEMİNDEN GİRİYORSUNUZ.",
["loc_bph_cbf_01"] = "DOSTLAR, ELEPHANT BANA BİRAZ İSTİHBARAT SAĞLADI VE BAIN'İN YERİNİ BULDUM. KATARU APTALLARI ONU İKİNCİ DÜNYA SAVAŞI'NDAN KALMA TERK EDİLMİŞ BİR HAPİSHANEDE TUTUYOR. TESİS, OREGON'UN KUZEY KIYISI AÇIKLARINDA, ULUSLARARASI SULARDAKİ BİR ADADA. MURKY'LER 70'LERDEN BERİ KULLANIYOR. BİRKAÇ KİŞİDEN RİCADA BULUNUP SİZE KÜÇÜK BİR SİVİL DENİZALTIDA YER AYARLADIM. BÖYLECE GİZLİCE GİRİP ADAMIMIZI GERİ ALABİLİRSİNİZ.",
["loc_bph_cnc_01"] = "TAMAM DOSTLAR. BAIN'İ KURTARMA VAKTİ.",
