["loc_bph_cnc_03"] = "GİDİP BAIN'İ ALMA VAKTİ.",
["loc_bph_end_fail_01"] = "DOSTLAR, BU BAŞARISIZ OLMA LÜKSÜMÜZÜN OLMADIĞI BİR İŞTİ. İYİ DEĞİL. HİÇ İYİ DEĞİL.",
["loc_bph_end_win_01"] = "İYİ İŞ ÇIKARDINIZ, DOSTLAR. İYİ İŞ! ADAMIMIZI GERİ ALDIK. BAIN... EVE DÖNDÜ. AMA MURKY'LER ONA BİR ŞEY YAPMIŞ. ŞU AN UZMANLAR MUAYENE EDİYOR. BİR TÜR VİRÜS OLDUĞUNU, BELKİ DE ÜRETİLMİŞ OLABİLECEĞİNİ SÖYLÜYORLAR. ÖLÜRSE... AH, ŞU LANET LOCKE ÇOK KIZACAK, KATARU'YA BUNU ÖDETECEK...",
["loc_bph_intro_01b"] = "SİZİN GİTMENİZ BENİM GİTMEMDEN İYİDİR, HA?",
["loc_brb_00_01"] = "TAMAM DOSTLAR, POLİSLERİN GELMESİNE FAZLA ZAMAN YOK. GİDİP BANKANIN İÇİNE BAKIN.",
["loc_brb_00_02"] = "O ARACIN PARASININ HAKKINI VERDİNİZ, HA? BANKANIN İÇİNE BAKMA VAKTİ. HIZLI OLUN DOSTLARIM.",
["loc_brb_00_03"] = "O ÇARPIŞMA ÖLÜLERİ BİLE UYANDIRMIŞTIR, HA? ÇABUK OLUN DA ŞU BANKAYA GİRİN.",
